e, _ := casbin.NewEnforcer("rbac_model.conf", "policy.csv")
// model.conf: [role_definition] g = _, _   [matchers] m = g(r.sub, p.sub) && r.obj == p.obj && r.act == p.act

func guard(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        p, ok := principal.From(r.Context())          // trusted subject, never r.Form/r.Header
        if !ok { http.Error(w, "unauthenticated", http.StatusUnauthorized); return }
        ok, err := e.Enforce(p.ID, r.URL.Path, r.Method)
        if err != nil || !ok { http.Error(w, "forbidden", http.StatusForbidden); return }  // deny by default
        next.ServeHTTP(w, r)
    })
}
